-- AccessCart demo catalog. Re-running this file refreshes existing IDs.
insert into public.products (id, name, category, price, rating, reviews_count, warranty_months, image_url, color, tag, description, simple_description, features, sample_reviews)
values
('p1', 'Soundcore Space One Headphones', 'Audio', 8999, 4.6, 284, 18, 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=900&q=85', '#f3e8dc', 'BEST VALUE', 'Comfortable over-ear headphones with adaptive noise cancelling and up to 40 hours of battery life.', 'Wireless headphones that block outside noise and last up to 40 hours on one charge.', array['Adaptive noise cancelling', '40-hour battery', 'Multipoint Bluetooth', 'USB-C fast charge']::text[], array['The battery lasts for days and the cushions are comfortable for long calls.', 'Noise cancellation works really well on the commute.', 'Great sound and very comfortable, but the case feels a little bulky.', 'Easy to connect to my laptop and phone at the same time.', 'Comfortable fit and excellent battery life for the price.']::text[]),
('p2', 'PixelTone Studio Wireless', 'Audio', 12499, 4.4, 167, 12, 'https://images.unsplash.com/photo-1546435770-a3e426bf472b?auto=format&fit=crop&w=900&q=85', '#e8ecf4', 'TOP RATED', 'Studio-tuned wireless headphones with rich sound, soft memory foam and clear voice pickup.', 'Wireless headphones with detailed sound and soft padding for everyday listening.', array['Studio-tuned drivers', '35-hour battery', 'Memory foam earcups', 'Voice assistant']::text[], array['Music sounds detailed and the earcups are very soft.', 'Calls are clear and setup took seconds.', 'Very good sound quality, though I wish charging was faster.', 'Comfortable all day and the battery is reliable.']::text[]),
('p3', 'Bose QuietComfort Lite', 'Audio', 18990, 4.7, 392, 24, 'https://images.unsplash.com/photo-1484704849700-f032a568e944?auto=format&fit=crop&w=900&q=85', '#e5e8e8', 'PREMIUM PICK', 'Lightweight headphones with world-class noise reduction, balanced audio and a two-year warranty.', 'Premium, light headphones that make noisy places quieter. Includes a two-year warranty.', array['Advanced noise reduction', '24-hour battery', 'Lightweight design', 'Fold-flat carry case']::text[], array['The noise cancelling is excellent on flights.', 'Very comfortable and the sound is balanced.', 'Build quality feels premium, but the price is high.', 'Battery lasts all day and the case is easy to pack.']::text[]),
('p4', 'AeroBrew Pour Over Set', 'Home & Kitchen', 2499, 4.3, 94, 12, 'https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?auto=format&fit=crop&w=900&q=85', '#e8eee6', 'SMALL JOY', 'A complete ceramic pour-over coffee set with a reusable filter and heat-safe server.', 'A ceramic coffee dripper and jug for making fresh pour-over coffee at home.', array['Heat-safe ceramic', 'Reusable steel filter', '600 ml server', 'Dishwasher safe']::text[], array['Makes a smooth cup and cleans up easily.', 'The ceramic feels sturdy and looks lovely.', 'Good value, but the filter lets a little sediment through.']::text[]),
('p5', 'Luma Desk Lamp Pro', 'Home & Kitchen', 3299, 4.5, 121, 24, 'https://images.unsplash.com/photo-1507473885765-e6ed057f782c?auto=format&fit=crop&w=900&q=85', '#e9eaf0', '', 'A dimmable LED desk lamp with warm-to-cool light, touch controls and a long-lasting LED panel.', 'A desk lamp with adjustable brightness and warm or cool light settings.', array['5 light temperatures', 'Touch dimmer', 'USB charging port', 'Two-year warranty']::text[], array['Perfect light for reading and the touch control is easy.', 'The brightness settings are useful and it uses little power.', 'Stable base and great build quality.']::text[]),
('p6', 'Terra Everyday Backpack', 'Travel', 4299, 4.2, 206, 12, 'https://images.unsplash.com/photo-1553062407-98eeb64c6a62?auto=format&fit=crop&w=900&q=85', '#e8eee8', '', 'A water-resistant 22-litre backpack with a padded laptop sleeve and thoughtful daily pockets.', 'A water-resistant backpack with space for a laptop and everyday essentials.', array['22 L capacity', 'Padded 15-inch laptop sleeve', 'Water-resistant shell', 'Luggage pass-through']::text[], array['Fits my laptop and gym gear with room to spare.', 'Comfortable straps and the fabric handles light rain.', 'Lots of useful pockets, though the bottle pocket is snug.']::text[]),
('p7', 'Roam Carry-On Cabin Case', 'Travel', 6999, 4.6, 173, 36, 'https://images.unsplash.com/photo-1565026057447-bc90a3dceb87?auto=format&fit=crop&w=900&q=85', '#f1e9dd', 'TRAVEL READY', 'A lightweight hard-shell cabin case with smooth spinner wheels and a three-year warranty.', 'A light cabin suitcase that rolls smoothly and is covered for three years.', array['Cabin size', '360° spinner wheels', 'TSA combination lock', 'Three-year warranty']::text[], array['Wheels roll smoothly and it fits the overhead bin.', 'The shell is light but feels sturdy.', 'Good organization inside, but the handle can wobble a little.']::text[]),
('p8', 'Kinto Insulated Bottle', 'Lifestyle', 1599, 4.4, 302, 12, 'https://images.unsplash.com/photo-1602143407151-7111542de6e8?auto=format&fit=crop&w=900&q=85', '#e4ece9', '', 'A double-wall stainless steel bottle that keeps drinks cold for 24 hours and hot for 8.', 'A reusable bottle that keeps cold drinks cold and hot drinks warm for hours.', array['750 ml capacity', '24-hour cold retention', 'Leak-resistant lid', 'BPA-free materials']::text[], array['Keeps water cold all day and never leaks in my bag.', 'Easy to clean and the finish still looks new.', 'Great bottle, although the lid is tricky to open one-handed.']::text[]),
('p9', 'Northstar Trail Sneakers', 'Lifestyle', 5499, 4.1, 148, 6, 'https://images.unsplash.com/photo-1542291026-7eec264c27ff?auto=format&fit=crop&w=900&q=85', '#f2e6e0', '', 'Lightweight everyday trail sneakers with grippy soles and breathable recycled mesh.', 'Light shoes with grippy soles for walking outdoors or around town.', array['Grippy rubber outsole', 'Breathable mesh upper', 'Recycled materials', 'Cushioned footbed']::text[], array['Comfortable for long walks and the grip is excellent.', 'Lightweight and breathable, but size runs a little small.', 'Great everyday shoe for the price.']::text[]),
('p10', 'Arc Mechanical Keyboard', 'Tech', 4799, 4.5, 189, 24, 'https://images.unsplash.com/photo-1587829741301-dc798b83add3?auto=format&fit=crop&w=900&q=85', '#e9eaf0', '', 'A compact mechanical keyboard with tactile quiet switches, hot-swap sockets and white backlighting.', 'A compact keyboard with satisfying keys, adjustable white lights and a long warranty.', array['75% compact layout', 'Hot-swappable switches', 'USB-C wired', 'Two-year warranty']::text[], array['Typing feels great and the keys are quieter than expected.', 'Solid build and easy to customize.', 'The compact layout takes a day to get used to.']::text[]),
('p11', 'Orbit Smartwatch Active', 'Tech', 7999, 4, 263, 12, 'https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&w=900&q=85', '#e8ebf3', '', 'A bright AMOLED smartwatch with activity tracking, sleep insights and up to seven days of battery.', 'A watch that tracks activity and sleep, with a screen you can easily read outside.', array['AMOLED display', '7-day battery', 'Sleep tracking', '5 ATM water resistance']::text[], array['Bright screen and accurate step tracking.', 'Battery lasts almost a week with normal use.', 'The app setup is confusing at first but works well after.']::text[]),
('p12', 'FocusFlow Ergonomic Mouse', 'Tech', 2199, 4.3, 117, 18, 'https://images.unsplash.com/photo-1527814050087-3793815479db?auto=format&fit=crop&w=900&q=85', '#e8e8e6', '', 'A comfortable wireless mouse with adjustable sensitivity and silent clicks for focused work.', 'A wireless mouse designed to feel comfortable and click quietly.', array['Ergonomic shape', 'Silent switches', 'Adjustable DPI', 'Bluetooth + USB receiver']::text[], array['My hand feels less tired after a full workday.', 'Silent clicks are great for shared spaces.', 'Comfortable, but the side buttons are easy to press by mistake.']::text[])
on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  price = excluded.price,
  rating = excluded.rating,
  reviews_count = excluded.reviews_count,
  warranty_months = excluded.warranty_months,
  image_url = excluded.image_url,
  color = excluded.color,
  tag = excluded.tag,
  description = excluded.description,
  simple_description = excluded.simple_description,
  features = excluded.features,
  sample_reviews = excluded.sample_reviews,
  updated_at = now();
